function parseCsv(text:string){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++;}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){row.push(cell.trim());cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=ch;}row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(rows.length<2)return[];const headers=rows[0].map(h=>h.toLowerCase().replace(/[^a-z]/g,''));const nameIndex=headers.findIndex(h=>['name','fullname','participantname'].includes(h)),emailIndex=headers.findIndex(h=>h==='email'||h==='emailaddress');if(nameIndex<0||emailIndex<0)throw new Error('CSV must include name and email columns.');return rows.slice(1).map(r=>({name:r[nameIndex]||'',email:r[emailIndex]||''})).filter(r=>r.name||r.email); }
