 const own=programs.filter(p=>user.organizationId===null||p.organizationId===user.organizationId);const selfOnly=can(user,'view','programs',{self:true})&&!can(user,'view','programs',{organizationId:user.organizationId||undefined,resourceOrganizationId:user.organizationId||undefined});const cofundedOnly=can(user,'view','programs',{coFunded:true,organizationId:user.organizationId||undefined,resourceOrganizationId:user.organizationId||undefined})&&!can(user,'view','programs',{organizationId:user.organizationId||undefined,resourceOrganizationId:user.organizationId||undefined})&&!selfOnly;const assignedOnly=can(user,'view','programs',{assigned:true,organizationId:user.organizationId||undefined,resourceOrganizationId:user.organizationId||undefined})&&!can(user,'view','programs',{organizationId:user.organizationId||undefined,resourceOrganizationId:user.organizationId||undefined})&&!selfOnly&&!cofundedOnly;const rows=[...created.filter(c=>!own.some(p=>p.id===c.id)),...own].filter(p=>(!assignedOnly||p.facilitatorIds.includes(user.id))&&(!cofundedOnly||p.sponsorOrganizationIds?.includes(user.organizationId||''))&&(!selfOnly||p.public||enrollments.some(e=>e.programId===p.id&&e.participantId===user.id))&&(statusFilter==='all'||p.status===statusFilter)&&p.title.toLowerCase().includes(query.toLowerCase()));const mayCreate=can(user,'create','programs',{organizationId:user.organizationId||undefined,resourceOrganizationId:user.organizationId||undefined});const detailRoster=detailProgram?enrollments.filter(e=>e.programId===detailProgram.id&&can(user,'view','participants',{organizationId:user.organizationId||undefined,resourceOrganizationId:e.organizationId,self:e.participantId===user.id,assigned:detailProgram.facilitatorIds.includes(user.id)})):[];const detailUnique=new Set(detailRoster.map(e=>e.participantId)).size;const detailCompleted=detailRoster.filter(e=>e.status==='completed').length;const detailActive=detailRoster.filter(e=>e.status==='enrolled').length;const detailWaitlisted