function RichText({name,placeholder,initial=''}:{name:string;placeholder:string;initial?:string}){const [html,setHtml]=useState(initial);function command(cmd:string){document.execCommand(cmd);const el=document.getElementById(`editor-${name}`);if(el)setHtml(el.innerHTML)}return <div className="rich-editor"><div className="rich-toolbar"><button type="button" onClick={()=>command('bold')}><b>B</b></button><button type="button" onClick={()=>command('italic')}><i>I</i></button><button type="button" onClick={()=>command('insertUnorderedList')}>• List</button><button type="button" onClick={()=>command('formatBlock')} >H</button></div><div id={`editor-${name}`} contentEditable suppressContentEditableWarning dangerouslySetInnerHTML={{__html:initial}} onInput={e=>setHtml(e.currentTarget.innerHTML)} data-placeholder={placeholder}/><input type="hidden" name={name} value={html}/></div>}

