 const learnerCount=allDirectoryRows.filter(u=>visibleParticipants.some(p=>p.id===u.id)).length,facilitatorCount=allDirectoryRows.filter(u=>visibleFacilitators.some(p=>p.id===u.id)).length,activeCount=allDirectoryRows.filter(u=>u.status==='active').length,restrictedCount=allDirectoryRows.filter(u=>u.status==='suspended'||u.status==='deactivated').length;
 async function sendInvite(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);let profile;try{profile=profilePatchFromForm(f)}catch(e){setMessage(e instanceof Error?e.message:'Please check profile fields.');return;}const roleIds=f.getAll('roleId').map(String),organizationId=user.organizationId||String(f.get('organizationId')||inviteOrg);if(!roleIds.length){setMessage('Select at least one role for this account.');return;}setBusy(true);const r=await mockApi.inviteUser(user as User,{name:String(f.get('name')),email:String(f.get('email')),roleIds,organizationId,profile});setBusy(false);if(r.ok){setInvite(false);toast('Account invitation created. Demo users can sign in with wego-demo.')}else setMessage(r.error.message)}
