 async function bulkStatus(status:User['status']){if(!selectedUsers.length){toast('Select accounts you have permission to edit.');return;}if((status==='suspended'||status==='deactivated')&&!window.confirm(`Change ${selectedUsers.length} selected accounts to ${status}?`))return;const results=await Promise.all(selectedUsers.map(u=>mockApi.updateUser(user as User,u.id,{name:u.name,email:u.email,roleIds:u.roleIds,status})));const failed=results.filter(r=>!r.ok).length;setRowSelection({});toast(failed?`${selectedUsers.length-failed} updated; ${failed} could not be changed.`:`${selectedUsers.length} accounts updated.`)}
 async function bulkAssignRole(){if(!bulkRole||!selectedUsers.length){toast('Choose a role and select accounts you have permission to edit.');return;}const results=await Promise.all(selectedUsers.map(u=>mockApi.updateUser(user as User,u.id,{name:u.name,email:u.email,roleIds:[...new Set([...u.roleIds,bulkRole])],status:u.status})));const failed=results.filter(r=>!r.ok).length;setRowSelection({});setBulkRole('');toast(failed?`${selectedUsers.length-failed} updated; ${failed} could not be changed.`:`Role assigned to ${selectedUsers.length} accounts.`)}
 async function bulkDelete(){const targets=allDirectoryRows.filter(u=>rowSelection[u.id]&&u.id!==user.id&&can(user,'delete','users',{organizationId:user.organizationId||undefined,resourceOrganizationId:u.organizationId||undefined}));if(!targets.length)return;if(!window.confirm(`Delete ${targets.length} selected account(s)? Linked learning history will be retained.`))return;const results=await Promise.all(targets.map(u=>mockApi.deleteUser(user as User,u.id)));const failed=results.filter(r=>!r.ok).length;setRowSelection({});toast(failed?`${targets.length-failed} deleted; ${failed} could not be deleted.`:`${targets.length} accounts deleted.`)}
